<?php require_once __DIR__.'/app/lib/Security.php';Security::start();Security::requireRole(['admin','super_admin']);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Audit Log · TechSelectAI</title><style>body{font-family:Inter,system-ui,sans-serif;background:#f6f8fb;color:#172033;margin:0}main{max-width:1300px;margin:auto;padding:28px}.filters{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}input,select,button,a.btn{padding:9px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;box-sizing:border-box}button,a.btn{background:#173b63;color:#fff;text-decoration:none;border:0;cursor:pointer}.toolbar{display:flex;justify-content:space-between;gap:12px;align-items:center}.muted{color:#64748b;font-size:12px}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px;border-bottom:1px solid #e8edf3;text-align:left;vertical-align:top}.diff{font-family:ui-monospace,monospace;font-size:11px;white-space:pre-wrap;max-width:420px}.pager{display:flex;gap:8px;margin:16px 0;align-items:center}@media(max-width:850px){main{padding:16px}.filters{grid-template-columns:1fr 1fr}table{display:block;overflow:auto}}@media(max-width:520px){.filters{grid-template-columns:1fr}}</style></head><body><main><div class="toolbar"><div><h1>Audit Log</h1><div class="muted">Searchable history of administrative and operational changes.</div></div><a id="export" class="btn" href="#">Export CSV</a></div><div class="filters"><input id="actor" type="number" placeholder="Actor user ID"><input id="action" placeholder="Action contains"><input id="etype" placeholder="Entity type"><input id="eid" placeholder="Entity ID"><select id="outcome"><option value="">All outcomes</option><option>success</option><option>failure</option></select><input id="from" type="date"><input id="to" type="date"><button onclick="page=1;load()">Filter</button></div><table><thead><tr><th>When / Actor</th><th>Action</th><th>Entity</th><th>Outcome</th><th>Before → After</th></tr></thead><tbody id="rows"></tbody></table><div class="pager"><button onclick="prev()">Previous</button><span id="pg"></span><button onclick="next()">Next</button></div></main><script>let page=1,pages=1;function e(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function params(){let p=new URLSearchParams({page});[['actor','actor_user_id'],['action','action'],['etype','entity_type'],['eid','entity_id'],['outcome','outcome'],['from','from'],['to','to']].forEach(([id,k])=>{let v=document.getElementById(id).value;if(v)p.set(k,v)});return p}async function load(){let p=params(),r=await fetch('/api/admin-governance/audit?'+p),d=await r.json();if(!r.ok)return alert(d.error||'Failed');pages=d.pages||1;pg.textContent=`Page ${d.page} of ${pages} · ${d.total} entries`;export.href='/api/admin-governance/audit.csv?'+p;rows.innerHTML=d.rows.map(x=>`<tr><td>${e(x.created_at)}<br><span class="muted">${e(x.actor_name||x.actor_email||x.actor_user_id||'system')}</span></td><td>${e(x.action)}</td><td>${x.link?`<a href="${e(x.link)}">${e(x.entity_type)} #${e(x.entity_id)}</a>`:`${e(x.entity_type)} #${e(x.entity_id||'')}`}</td><td>${e(x.outcome)}</td><td><details><summary>View diff</summary><div class="diff">Before: ${e(JSON.stringify(x.before,null,2))}\nAfter: ${e(JSON.stringify(x.after,null,2))}</div></details></td></tr>`).join('')}function prev(){if(page>1){page--;load()}}function next(){if(page<pages){page++;load()}}load();</script></body></html>